// ─── Test Runner ──────────────────────────────────────────────────

export function runPullBoxSizingTests() {
  const results = [];
  let passed = 0;
  let failed = 0;

  for (const test of TESTS) {
    const actual = calcPullBoxSizing(test.inputs, NEC);
    const matches = {};
    let allMatch = true;

    for (const [key, expectedVal] of Object.entries(test.expected)) {
      let actualVal;
      let match;

      if (key === "applicable") {
        actualVal = actual.applicable;
        match = actualVal === expectedVal;
      } else if (key === "pass") {
        actualVal = actual.pass;
        match = actualVal === expectedVal;
      } else if (key === "connectedSpacing") {
        const connSpacing = actual.spacingRequirements?.find(s => s.type === "connected");
        actualVal = connSpacing?.requiredSpacing ?? 0;
        match = withinTolerance(actualVal, expectedVal);
      } else if (key === "anglePullSpacing") {
        const angleSpacing = actual.spacingRequirements?.find(s => s.type === "connected" && s.pathType === "angle");
        actualVal = angleSpacing?.requiredSpacing ?? 0;
        match = withinTolerance(actualVal, expectedVal);
      } else if (key === "spacingCount") {
        actualVal = actual.spacingRequirements?.length ?? 0;
        match = actualVal === expectedVal;
      } else if (key === "straightPullCount") {
        actualVal = actual.straightPullTraces?.length ?? 0;
        match = actualVal === expectedVal;
      } else if (key === "wallRowCount") {
        actualVal = actual.wallRowTraces?.length ?? 0;
        match = actualVal === expectedVal;
      } else if (key === "hasApplicabilityWarning") {
        actualVal = !!actual.applicabilityWarning;
        match = actualVal === expectedVal;
      } else {
        actualVal = actual[key];
        match = withinTolerance(actualVal, expectedVal);
      }

      matches[key] = { actual: actualVal, expected: expectedVal, match };
      if (!match) allMatch = false;
    }

    if (allMatch) passed++;
    else failed++;

    results.push({
      id: test.id,
      name: test.name,
      note: test.note,
      source: test.source || null,
      result: allMatch ? "PASS" : "FAIL",
      matches,
      actual: {
        minX: actual.minX,
        minY: actual.minY,
        applicable: actual.applicable,
        pass: actual.pass,
        spacingRequirements: actual.spacingRequirements,
        wallRowTraces: actual.wallRowTraces,
        straightPullTraces: actual.straightPullTraces,
        xAxisMessage: actual.xAxisMessage,
        yAxisMessage: actual.yAxisMessage,
        conductorSizeNotice: actual.conductorSizeNotice,
        applicabilityWarning: actual.applicabilityWarning,
      },
    });
  }

  return { results, passed, failed, total: TESTS.length };
}